:root {
  --bg: #05070c;
  --panel: #0c1119;
  --panel-2: #10161f;
  --border: #1c2634;
  --text: #e2e8f0;
  --text-dim: #7d8ba0;
  --accent: #38bdf8;
  --mono: "SF Mono", "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;

  --c-idle: #475569;
  --c-running: #3b82f6;
  --c-pass: #22c55e;
  --c-fail: #ef4444;
  --c-stalled: #f59e0b;
  --c-error: #ef4444;

  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html, body, #root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background-image:
    radial-gradient(circle at 20% 0%, rgba(56, 189, 248, 0.06), transparent 40%),
    radial-gradient(circle at 80% 100%, rgba(56, 189, 248, 0.04), transparent 40%);
}

.app {
  min-height: 100%;
  display: flex;
  flex-direction: column;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 24px;
  border-bottom: 1px solid var(--border);
  background: rgba(12, 17, 25, 0.8);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 10;
}

.app-title {
  font-family: var(--mono);
  font-size: 13px;
  letter-spacing: 0.12em;
  color: var(--text);
  font-weight: 600;
}

.app-title-mark {
  color: var(--accent);
  margin-right: 8px;
}

.app-header-right {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--mono);
  font-size: 11px;
  color: var(--text-dim);
}

.app-branch {
  padding: 2px 8px;
  border: 1px solid var(--border);
  border-radius: 4px;
  color: var(--accent);
}

.conn-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
}

.conn-on {
  background: var(--c-pass);
  box-shadow: 0 0 6px var(--c-pass);
}

.conn-off {
  background: var(--c-fail);
}

.app-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 24px;
  border-bottom: 1px solid var(--border);
}

.app-controls select,
.app-controls button {
  font-family: var(--mono);
  font-size: 12px;
  background: var(--panel-2);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 8px 12px;
}

.app-controls button {
  background: var(--accent);
  color: #04141f;
  font-weight: 600;
  cursor: pointer;
  border: none;
}

.app-controls button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.app-launch-error {
  color: var(--c-fail);
  font-family: var(--mono);
  font-size: 12px;
}

.app-main {
  flex: 1;
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 20px;
  padding: 24px;
  align-items: start;
}

.app-graph-section,
.app-proof-section {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Pipeline graph */

.pipeline-graph {
  display: flex;
  align-items: center;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 28px 20px;
  overflow-x: auto;
}

.pipeline-node-wrap {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
}

.pipeline-edge {
  flex: 1;
  height: 2px;
  position: relative;
  min-width: 24px;
  margin: 0 4px;
}

.pipeline-edge-line {
  height: 2px;
  background: var(--border);
  width: 100%;
}

.pipeline-edge-active .pipeline-edge-line {
  background: var(--accent);
}

.pipeline-edge-pulse {
  position: absolute;
  top: -3px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent);
  animation: travel 1.1s linear infinite;
}

@keyframes travel {
  from { left: 0%; opacity: 1; }
  to { left: 96%; opacity: 0.2; }
}

.pipeline-node {
  --node-color: var(--c-idle);
  flex-shrink: 0;
  width: 108px;
  border: 1px solid var(--node-color);
  border-radius: 10px;
  padding: 12px 10px;
  text-align: center;
  background: var(--panel-2);
  position: relative;
}

.pipeline-node-gate {
  border-radius: 6px;
  transform: rotate(0deg);
  border-style: dashed;
}

.pipeline-node-running {
  animation: glow 1.4s ease-in-out infinite;
}

@keyframes glow {
  0%, 100% { box-shadow: 0 0 0px var(--node-color); }
  50% { box-shadow: 0 0 14px var(--node-color); }
}

.pipeline-node-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--node-color);
  margin: 0 auto 8px;
}

.pipeline-node-label {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.06em;
  color: var(--text);
  text-transform: uppercase;
}

.pipeline-node-status {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--node-color);
  margin-top: 4px;
  text-transform: uppercase;
}

.pipeline-node-count {
  font-family: var(--mono);
  font-size: 10px;
  color: var(--text-dim);
  margin-top: 2px;
}

/* Agent status list */

.agent-status {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px 18px;
}

.agent-status h3,
.proof-panel h3 {
  margin: 0 0 12px;
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-dim);
  font-family: var(--mono);
}

.agent-status-empty,
.proof-empty,
.waveform-empty {
  color: var(--text-dim);
  font-family: var(--mono);
  font-size: 12px;
}

.agent-status-row {
  border-left: 2px solid var(--c-idle);
  padding: 8px 10px;
  margin-bottom: 6px;
  background: var(--panel-2);
  border-radius: 0 6px 6px 0;
}

.agent-status-row.status-pass { border-color: var(--c-pass); }
.agent-status-row.status-fail { border-color: var(--c-fail); }
.agent-status-row.status-error { border-color: var(--c-error); }
.agent-status-row.status-stalled { border-color: var(--c-stalled); }
.agent-status-row.status-running { border-color: var(--c-running); }

.agent-status-top {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 11px;
}

.agent-status-agent {
  text-transform: uppercase;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.agent-status-stage {
  color: var(--text-dim);
}

.agent-status-badge {
  margin-left: auto;
  padding: 1px 6px;
  border-radius: 4px;
  font-size: 10px;
}

.badge-pass { background: rgba(34,197,94,0.15); color: var(--c-pass); }
.badge-fail { background: rgba(239,68,68,0.15); color: var(--c-fail); }
.badge-error { background: rgba(239,68,68,0.15); color: var(--c-error); }
.badge-stalled { background: rgba(245,158,11,0.15); color: var(--c-stalled); }
.badge-running { background: rgba(59,130,246,0.15); color: var(--c-running); }

.agent-status-detail {
  font-size: 11px;
  color: var(--text-dim);
  margin-top: 4px;
  word-break: break-word;
}

.agent-status-link {
  font-size: 11px;
  color: var(--accent);
  text-decoration: none;
  display: inline-block;
  margin-top: 4px;
}

/* Proof panel */

.proof-panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px;
}

.proof-section {
  margin-bottom: 22px;
}

.proof-section:last-child {
  margin-bottom: 0;
}

.proof-section-title {
