import { chromium } from "playwright";

const errors = [];
const browser = await chromium.launch();
const page = await browser.newPage();
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(msg.text());
});
page.on("pageerror", (err) => errors.push(String(err)));

await page.goto("http://localhost:5173/", { waitUntil: "networkidle" });
await page.waitForSelector("text=CHIP RECREATION");

await page.screenshot({ path: "scratch_before.png", fullPage: true });
console.log("BEFORE screenshot taken");

// confirm chip selector populated from /api/chips
await page.waitForSelector("select");
const options = await page.$$eval("select option", (opts) => opts.map((o) => o.value));
console.log("chip options:", options);

await page.click("button:has-text('Launch Attempt')");
console.log("clicked Launch Attempt");

// wait for a live agent-status row to appear (proves SSE -> React state works)
await page.waitForSelector(".agent-status-row", { timeout: 20000 });
await page.waitForTimeout(1500);

await page.screenshot({ path: "scratch_after.png", fullPage: true });
console.log("AFTER screenshot taken");

const connLabel = await page.$eval(".conn-label", (el) => el.textContent);
console.log("connection label:", connLabel);

const nodeStatuses = await page.$$eval(".pipeline-node", (nodes) =>
  nodes.map((n) => ({
    label: n.querySelector(".pipeline-node-label")?.textContent,
    status: n.querySelector(".pipeline-node-status")?.textContent,
  }))
);
console.log("pipeline node statuses:", JSON.stringify(nodeStatuses));

console.log("console errors:", JSON.stringify(errors));

await browser.close();

